function probeTable(keys, size) {
  if (!Number.isInteger(size) || size < 1 || size > 1000)
    throw new RangeError("Use a table size from 1 through 1000");
  if (!Array.isArray(keys) ||
      !Array.from(keys).every(k => typeof k === "bigint"))
    throw new TypeError("Use an array of BigInt keys");
  const slots = Array(size).fill(null);
  for (const key of keys) {
    const m = BigInt(size);
    const home = Number(((key % m) + m) % m);
    let placed = false;
    for (let i = 0; i < size; i++) {
      const position = (home + i) % size;
      if (slots[position] === null || slots[position] === key) {
        slots[position] = key;
        placed = true;
        break;
      }
    }
    if (!placed) throw new RangeError("The table is full");
  }
  return slots;
}

function lcg(m, a, c, seed, steps) {
  if ([m, a, c, seed].some(x => typeof x !== "bigint"))
    throw new TypeError("Use BigInt parameters");
  if (m <= 2n || a < 2n || a >= m || c < 0n || c >= m ||
      seed < 0n || seed >= m)
    throw new RangeError("Require 2 <= a < m and 0 <= c,seed < m");
  if (!Number.isInteger(steps) || steps < 0 || steps > 10000)
    throw new RangeError("Use 0 through 10000 steps");
  let x = seed;
  const states = [x];
  for (let i = 0; i < steps; i++) {
    x = (a * x + c) % m;
    states.push(x);
  }
  return states;
}

function appendEvenParity(bits) {
  if (typeof bits !== "string" || !/^[01]*$/.test(bits))
    throw new TypeError("Use a binary string");
  let parity = 0;
  for (const bit of bits) parity = (parity + Number(bit)) % 2;
  return bits + String(parity);
}

function validEvenParity(bits) {
  if (typeof bits !== "string" || !/^[01]+$/.test(bits)) return false;
  let sum = 0;
  for (const bit of bits) sum += Number(bit);
  return sum % 2 === 0;
}

function isbn10CheckDigit(payload) {
  if (typeof payload !== "string" || !/^[0-9]{9}$/.test(payload))
    throw new TypeError("Use exactly nine decimal digits");
  let sum = 0;
  for (let i = 0; i < 9; i++) sum += (i + 1) * Number(payload[i]);
  const check = sum % 11;
  return check === 10 ? "X" : String(check);
}

function validIsbn10(code) {
  if (typeof code !== "string" || !/^[0-9]{9}[0-9X]$/.test(code)) return false;
  return isbn10CheckDigit(code.slice(0, 9)) === code[9];
}

function retailCheckDigit(payload) {
  if (typeof payload !== "string" || !/^(?:[0-9]{11}|[0-9]{12})$/.test(payload))
    throw new TypeError("Use 11 or 12 decimal digits, with no separators");
  let sum = 0, weight = 3;
  for (let i = payload.length - 1; i >= 0; i--) {
    sum += weight * Number(payload[i]);
    weight = 4 - weight;
  }
  return String((10 - sum % 10) % 10);
}

function validRetailCode(code) {
  if (typeof code !== "string" || !/^(?:[0-9]{12}|[0-9]{13})$/.test(code))
    return false;
  return retailCheckDigit(code.slice(0, -1)) === code.at(-1);
}
